   321	/**
   322	 * This function will reset the preferred exporter to the owner of the workspace
   323	 * if the current preferred exporter is removed from the admin role.
   324	 * @param [policyID] The id of the policy.
   325	 * @param [loginList] The logins of the users whose roles are being updated to non-admin role or are removed from a workspace
   326	 */
   327	function resetAccountingPreferredExporter(policyID: string, loginList: string[]): OnyxDataReturnType {
   328	    // This will be fixed as part of https://github.com/Expensify/Expensify/issues/507850
   329	    // eslint-disable-next-line deprecation/deprecation
   330	    const policy = getPolicy(policyID);
   331	    const owner = policy?.owner ?? ReportUtils.getPersonalDetailsForAccountID(policy?.ownerAccountID).login ?? '';
   332	    const optimisticData: OnyxUpdate[] = [];
   333	    const successData: OnyxUpdate[] = [];
   334	    const failureData: OnyxUpdate[] = [];
   335	    const policyKey = `${ONYXKEYS.COLLECTION.POLICY}${policyID}` as const;
   336	    const adminLoginList = loginList.filter((login) => isUserPolicyAdmin(policy, login));
   337	    const connections = [CONST.POLICY.CONNECTIONS.NAME.XERO, CONST.POLICY.CONNECTIONS.NAME.QBO, CONST.POLICY.CONNECTIONS.NAME.SAGE_INTACCT, CONST.POLICY.CONNECTIONS.NAME.QBD];
   338	
   339	    if (!adminLoginList.length) {
   340	        return {optimisticData, successData, failureData};
   341	    }
   342	
   343	    connections.forEach((connection) => {
   344	        const exporter = policy?.connections?.[connection]?.config.export.exporter;
   345	        if (!exporter || !adminLoginList.includes(exporter)) {
   346	            return;
   347	        }
   348	
   349	        const pendingFieldKey = connection === CONST.POLICY.CONNECTIONS.NAME.QBO ? CONST.QUICKBOOKS_CONFIG.EXPORT : CONST.QUICKBOOKS_CONFIG.EXPORTER;
   350	        optimisticData.push({
   351	            onyxMethod: Onyx.METHOD.MERGE,
   352	            key: policyKey,
   353	            value: {
   354	                connections: {
   355	                    [connection]: {
   356	                        config: {
   357	                            export: {exporter: owner},
   358	                            pendingFields: {[pendingFieldKey]: CONST.RED_BRICK_ROAD_PENDING_ACTION.UPDATE},
   359	                        },
   360	                    },
   361	                },
   362	            },
   363	        });
   364	        successData.push({
   365	            onyxMethod: Onyx.METHOD.MERGE,
   366	            key: policyKey,
   367	            value: {
   368	                connections: {[connection]: {config: {pendingFields: {[pendingFieldKey]: null}}}},
   369	            },
   370	        });
   371	        failureData.push({
   372	            onyxMethod: Onyx.METHOD.MERGE,
   373	            key: policyKey,
   374	            value: {
   375	                connections: {
   376	                    [connection]: {
   377	                        config: {
   378	                            export: {exporter: policy?.connections?.[connection]?.config.export.exporter},
   379	                            pendingFields: {[pendingFieldKey]: null},
   380	                        },
   381	                    },
   382	                },
   383	            },
   384	        });
   385	    });
   386	
   387	    const exporter = policy?.connections?.netsuite?.options.config.exporter;
   388	    if (exporter && adminLoginList.includes(exporter)) {
   389	        optimisticData.push({
   390	            onyxMethod: Onyx.METHOD.MERGE,
   391	            key: policyKey,
   392	            value: {
   393	                connections: {netsuite: {options: {config: {exporter: owner, pendingFields: {exporter: CONST.RED_BRICK_ROAD_PENDING_ACTION.UPDATE}}}}},
   394	            },
   395	        });
   396	        successData.push({
   397	            onyxMethod: Onyx.METHOD.MERGE,
   398	            key: policyKey,
   399	            value: {
   400	                connections: {netsuite: {options: {config: {pendingFields: {exporter: null}}}}},
   401	            },
   402	        });
   403	        failureData.push({
   404	            onyxMethod: Onyx.METHOD.MERGE,
   405	            key: policyKey,
   406	            value: {connections: {netsuite: {options: {config: {exporter: policy?.connections?.netsuite?.options.config.exporter, pendingFields: {exporter: null}}}}}},
   407	        });
   408	    }
   409	
   410	    return {optimisticData, successData, failureData};
   411	}
